(function(){const a=document.querySelector('aside');if(!a)return;const cur=location.pathname.split('/').pop();
 ['01','02','03','04','05'].forEach(n=>{const href='week'+n+'.html';if(a.querySelector('a[href="'+href+'"]'))return;
  const l=document.createElement('a');l.href=href;l.dataset.i18n='week';l.dataset.n=n;l.textContent='Week '+n;if(cur===href)l.className='active';a.appendChild(l)})})();
Object.assign(i18n.en,{"w5h": "Press-fit elephant chair - CAD design, laser cutting in MDF and assembly manual", "w5s1T": "1. Project Summary and Components", "w5s1p": "Digital design and fabrication of a chair with an elephant silhouette in 3 mm MDF, developed with the press-fit system (joints held together by pressure). The model is assembled in 4 steps using only 13 pieces, with no screws, nails, or glue.", "w5c1": "3 mm MDF", "w5c2": "13 pieces", "w5c3": "4 steps", "w5swT": "Software used: ", "w5sw": "Autodesk Fusion for the 2D CAD design and RDWorks V8 to prepare the files for the laser cutter.", "w5thCode": "Code", "w5thComp": "Component", "w5thQty": "Qty.", "w5thFunc": "Main function in the design", "w5piece": "Piece {n}", "w5p1n": "Elephant sides", "w5p1f": "Side structure with 5 square cutouts and a comb-type slot (6 notches).", "w5p2n": "Connecting bars", "w5p2f": "Crossbars with tabs at the ends (3 for the backrest on the trunk and 2 on the legs).", "w5p3n": "Seat slats", "w5p3f": "Slats with lower notches that fit across the central comb.", "w5s2T": "2. Creation Process (From CAD to Laser Cutting)", "w5ph1T": "Phase 1: Sketching and 2D CAD modeling (Fusion)", "w5ph1": "Tracing the elephant silhouette, using the curve of the trunk as an ergonomic backrest. The slots were parameterized according to the MDF thickness (3 mm) and the laser tolerance (kerf) to achieve a firm fit.", "w5ph2T": "Phase 2: Joint engineering (press-fit system)", "w5ph2": "Design of two joining mechanisms: (1) five square through-holes along the trunk and the legs for the crossbars (Piece 2), and (2) a central toothed “comb” cutout with 6 slots for the seat slats to cross (Piece 3).", "w5ph3T": "Phase 3: Digital fabrication (laser cutting)", "w5ph3": "Export of the 2D vectors for laser cutting in MDF, achieving millimetric precision in the tabs and notches to guarantee structural stability without adhesives.", "w5ph4T": "Phase 4: User manual development", "w5ph4": "Creation of an illustrated foldable guide with 8 sections, including a visual inventory of the 13 pieces, the 4 assembly steps, a graphic summary, and adjustment tips.", "w5f1": "Fig. 1: 2D parametric design in Fusion (Pieces 1, 2, and 3).", "w5f2": "Fig. 2: Final chair, laser cut and assembled in MDF.", "w5s3T": "3. The Main Challenge: The Kerf", "w5k1": "The hardest part of this project was working with the kerf to make the pieces join. The laser removes a thin strip of material along every cut, so a slot comes out wider and a tab comes out thinner than drawn. Because our chair has no screws or glue, every joint depends on that tolerance.", "w5k2": "A slot that is too wide leaves the piece loose, and one that is too tight will not go in. To control this, we parameterized the slots in Fusion using the MDF thickness (3 mm) and the kerf as variables, so changing one value updated every slot before exporting again to the laser cutter. A common rule for press-fit slots is to draw them slightly narrower than the material thickness, by about the kerf, so that the final cut matches the thickness.", "w5k3": "Even so, finding a fit that was firm without forcing the pieces was difficult. If a joint is too tight, the assembly guide recommends not forcing the pieces and lightly sanding the edges.", "w5s4T": "4. Step-by-Step Assembly", "w5st1T": "Step 1 – Bars on the first elephant (5x)", "w5st1": "Lay one elephant side (Piece 1) down with the flat face up. Insert one bar (Piece 2) into each of the 5 square holes (3 on the trunk/back and 1 on each leg), pressing all the way in so they stand like posts.", "w5st2T": "Step 2 – Cover with the second elephant", "w5st2": "Place the second elephant facing the same direction as the first (not mirrored). Align its 5 holes with the tips of the bars and lower it evenly, pressing first in the center and then at the corners.", "w5st3T": "Step 3 – Stand it up", "w5st3": "Turn the structure over and rest it on its 4 legs. Move it slightly to check its firmness; if it wobbles, press the sides against the bars again.", "w5st4T": "Step 4 – Place the 6 seat slats (6x)", "w5st4": "Locate the central “comb” (6 slots on each elephant). Orient each slat (Piece 3) with the notches facing down, fit one end into each side evenly, and press them in one by one until they are flush, without forcing.", "w5f3": "Fig. 3: Assembly manual (cover, parts inventory, and summary).", "w5f4": "Fig. 4: Assembly manual (detail of the 4 assembly steps).", "w5chkT": "Final check", "w5chk": "Make sure the 5 bars are firm, the 6 slats are flush in place, and the chair does not wobble.", "w5fixT": "If something does not fit", "w5fix": "Do not force the pieces. Check that it is the right piece, make sure both elephants face the same direction, and, if the fit is too tight, lightly sand the edges.", "w5s5T": "5. Pros and Cons of Building a Chair in MDF", "w5s5p": "MDF is the material we used, so we looked into what it offers for a chair and where it falls short.", "w5proT": "Pros", "w5conT": "Cons", "w5pr1": "Low cost compared with plywood and many natural woods.", "w5pr2": "Smooth, uniform surface with no knots or grain, so it cuts cleanly and takes paint well.", "w5pr3": "Consistent in strength and size, and with no grain it has little tendency to split.", "w5pr4": "Easy to cut and shape; on the laser cutter it gave us millimetric precision in tabs and notches.", "w5pr5": "Flat sheets suit flat-pack, press-fit designs: our chair needs only 13 flat pieces and no hardware.", "w5pr6": "It is made from wood-fibre residues, which reduces the demand for solid timber.", "w5cn1": "Poor moisture resistance: standard MDF can swell and warp when it gets wet, so it is not suited to humid or outdoor places unless it is sealed or a moisture-resistant grade is used.", "w5cn2": "Heavy compared with plywood.", "w5cn3": "Softer and weaker than plywood or solid wood: it can sag under heavy weight, so a full-size chair would need thicker boards or reinforcement.", "w5cn4": "Poor screw holding, especially at the edges, which is one more reason to join it with press-fit joints.", "w5cn5": "Cutting and sanding release fine dust, and the resin binder can release formaldehyde, so it needs good ventilation and a respirator.", "w5cn6": "Laser cutting can burn the edges, and the kerf must be compensated carefully for the joints to fit.", "w5vT": "Our takeaway: ", "w5v": "MDF is an excellent material for prototypes and small press-fit models like ours: it is cheap, cuts cleanly, and is easy to work with. For a full-size chair that will carry weight or be used in humid places, a thicker board, reinforcement, sealing, or a different material such as plywood would likely be a better choice.", "w5conclT": "Conclusion", "w5concl1": "In this project we went from a sketch to a real chair, working in CAD (Autodesk Fusion) to design the pieces and in RDWorks to prepare the laser cutting. The hardest part was the kerf: since all the pieces join by pressure, a fraction of a millimeter decided whether a joint was loose or too tight. Parameterizing the slots helped us adjust the design without redrawing it.", "w5concl2": "In general, it was an interesting experience. We saw how a design can become a product that assembles in four steps with only 13 pieces and no screws or glue, and we learned the strengths and limits of MDF as a material for furniture.", "w5bibT": "References"});
Object.assign(i18n.es,{"w5h": "Silla elefante armable por encaje - Diseño CAD, corte láser en MDF y manual de ensamblaje", "w5s1T": "1. Resumen del proyecto y componentes", "w5s1p": "Diseño y fabricación digital de una silla con silueta de elefante en MDF de 3 mm, desarrollada con el sistema press-fit (unión por encaje a presión). El modelo se ensambla en 4 pasos utilizando únicamente 13 piezas, sin necesidad de tornillos, clavos ni adhesivos.", "w5c1": "MDF de 3 mm", "w5c2": "13 piezas", "w5c3": "4 pasos", "w5swT": "Software utilizado: ", "w5sw": "Autodesk Fusion para el diseño CAD 2D y RDWorks V8 para preparar los archivos de la cortadora láser.", "w5thCode": "Código", "w5thComp": "Componente", "w5thQty": "Cant.", "w5thFunc": "Función principal en el diseño", "w5piece": "Pieza {n}", "w5p1n": "Laterales de elefante", "w5p1f": "Estructura base lateral con 5 calados cuadrados y ranura tipo peine (6 muescas).", "w5p2n": "Barras de unión", "w5p2f": "Travesaños con espigas en los extremos (3 para el respaldar en la trompa y 2 en las patas).", "w5p3n": "Tablillas de asiento", "w5p3f": "Listones con muescas inferiores que encajan transversalmente sobre el peine central.", "w5s2T": "2. Proceso de creación (de CAD a corte láser)", "w5ph1T": "Fase 1: Bocetado y modelado CAD 2D (Fusion)", "w5ph1": "Trazado de la silueta del elefante aprovechando la curvatura de la trompa como respaldar ergonómico. Se parametrizaron las ranuras según el espesor del MDF (3 mm) y la tolerancia del láser (kerf) para lograr un ajuste firme.", "w5ph2T": "Fase 2: Ingeniería de encajes (sistema press-fit)", "w5ph2": "Diseño de dos mecanismos de unión: (1) cinco perforaciones cuadradas pasantes distribuidas en la trompa y las patas para las barras transversales (Pieza 2), y (2) un calado central dentado tipo “peine” con 6 ranuras para cruzar las tablillas del asiento (Pieza 3).", "w5ph3T": "Fase 3: Fabricación digital (corte láser)", "w5ph3": "Exportación de los vectores 2D para corte láser en MDF, logrando precisión milimétrica en las espigas y muescas para garantizar estabilidad estructural sin adhesivos.", "w5ph4T": "Fase 4: Desarrollo del manual de usuario", "w5ph4": "Elaboración de una guía plegable ilustrada de 8 secciones que incluye inventario visual de las 13 piezas, los 4 pasos de armado, resumen gráfico y consejos de ajuste.", "w5f1": "Fig. 1: Diseño paramétrico 2D en Fusion (Piezas 1, 2 y 3).", "w5f2": "Fig. 2: Silla final cortada en láser y ensamblada en MDF.", "w5s3T": "3. El mayor reto: el kerf", "w5k1": "Lo más difícil de este proyecto fue trabajar el kerf para lograr que las piezas se unieran. El láser retira una franja fina de material en cada corte, por lo que una ranura sale más ancha y una espiga más delgada de lo dibujado. Como nuestra silla no lleva tornillos ni pegamento, cada unión depende de esa tolerancia.", "w5k2": "Una ranura demasiado ancha deja la pieza floja y una demasiado justa no entra. Para controlarlo, parametrizamos las ranuras en Fusion usando el espesor del MDF (3 mm) y el kerf como variables, de modo que al cambiar un solo valor se actualizaban todas las ranuras antes de volver a exportar a la cortadora láser. Una regla común para las uniones press-fit es dibujar las ranuras un poco más angostas que el espesor del material, aproximadamente en el valor del kerf, para que el corte final coincida con el espesor.", "w5k3": "Aun así, encontrar un ajuste firme sin forzar las piezas fue complicado. Si una unión queda muy apretada, la guía de armado recomienda no forzar las piezas y lijar suavemente los bordes.", "w5s4T": "4. Paso a paso de armado", "w5st1T": "Paso 1 – Barras en el primer elefante (5x)", "w5st1": "Acostar un lateral de elefante (Pieza 1) con la cara plana hacia arriba. Insertar una barra (Pieza 2) en cada uno de los 5 huecos cuadrados (3 en la trompa/lomo y 1 en cada pata), presionando hasta el fondo para que queden paradas como postes.", "w5st2T": "Paso 2 – Cubrir con el segundo elefante", "w5st2": "Colocar el segundo elefante mirando hacia el mismo lado que el primero (no en espejo). Alinear sus 5 huecos con las puntas de las barras y bajarlo parejo, presionando primero al centro y luego en las esquinas.", "w5st3T": "Paso 3 – Ponerlo de pie", "w5st3": "Girar la estructura y apoyarla sobre sus 4 patas. Moverla ligeramente para comprobar la firmeza; si tiene juego, presionar nuevamente los laterales contra las barras.", "w5st4T": "Paso 4 – Colocar las 6 tablillas del asiento (6x)", "w5st4": "Ubicar el “peine” central (6 ranuras en cada elefante). Orientar cada tablilla (Pieza 3) con las muescas hacia abajo, encajar una punta en cada lateral bien pareja y presionar una por una hasta que queden al ras, sin forzar.", "w5f3": "Fig. 3: Manual de armado (portada, inventario de piezas y resumen).", "w5f4": "Fig. 4: Manual de armado (detalle de los 4 pasos de ensamble).", "w5chkT": "Verificación final", "w5chk": "Verificar que las 5 barras hayan quedado firmes, que las 6 tablillas estén al ras en su sitio y que la silla no se tambalee.", "w5fixT": "Si algo no entra", "w5fix": "No forzar las piezas. Revisar que sea la pieza correcta, comprobar que ambos elefantes miren al mismo lado y, si el encaje está muy apretado, lijar suavemente los bordes.", "w5s5T": "5. Pros y contras de construir una silla en MDF", "w5s5p": "El MDF es el material que usamos, así que investigamos qué ofrece para una silla y dónde se queda corto.", "w5proT": "Pros", "w5conT": "Contras", "w5pr1": "Bajo costo en comparación con el contrachapado y muchas maderas naturales.", "w5pr2": "Superficie lisa y uniforme, sin nudos ni vetas, por lo que corta limpio y recibe bien la pintura.", "w5pr3": "Resistencia y tamaño consistentes; al no tener veta, casi no tiende a rajarse.", "w5pr4": "Fácil de cortar y dar forma; en la cortadora láser nos dio precisión milimétrica en espigas y muescas.", "w5pr5": "Las planchas planas se adaptan a diseños desarmables press-fit: nuestra silla solo necesita 13 piezas planas y ninguna herramienta de unión.", "w5pr6": "Se fabrica con residuos de fibra de madera, lo que reduce la demanda de madera maciza.", "w5cn1": "Poca resistencia a la humedad: el MDF estándar puede hincharse y deformarse al mojarse, por lo que no es apto para lugares húmedos o exteriores, salvo que se selle o se use un tipo resistente a la humedad.", "w5cn2": "Pesado en comparación con el contrachapado.", "w5cn3": "Más blando y débil que el contrachapado o la madera maciza: puede pandearse con mucho peso, por lo que una silla de tamaño real necesitaría tableros más gruesos o refuerzos.", "w5cn4": "Sujeta mal los tornillos, sobre todo en los bordes, una razón más para unirlo con encajes press-fit.", "w5cn5": "Al cortarlo y lijarlo libera polvo fino y la resina que lo une puede liberar formaldehído, por lo que requiere buena ventilación y mascarilla.", "w5cn6": "El corte láser puede quemar los bordes y el kerf debe compensarse con cuidado para que las uniones encajen.", "w5vT": "Nuestra conclusión: ", "w5v": "El MDF es un excelente material para prototipos y modelos press-fit pequeños como el nuestro: es barato, corta limpio y es fácil de trabajar. Para una silla de tamaño real que soporte peso o se use en lugares húmedos, probablemente sea mejor un tablero más grueso, refuerzos, sellado u otro material como el contrachapado.", "w5conclT": "Conclusión", "w5concl1": "En este proyecto pasamos de un boceto a una silla real, trabajando en CAD (Autodesk Fusion) para diseñar las piezas y en RDWorks para preparar el corte láser. Lo más difícil fue el kerf: como todas las piezas se unen a presión, una fracción de milímetro decidía si una unión quedaba floja o demasiado apretada. Parametrizar las ranuras nos ayudó a ajustar el diseño sin volver a dibujarlo.", "w5concl2": "En general, fue una experiencia interesante. Vimos cómo un diseño puede convertirse en un producto que se arma en cuatro pasos con solo 13 piezas y sin tornillos ni pegamento, y aprendimos las fortalezas y los límites del MDF como material para muebles.", "w5bibT": "Referencias"});
let lang='en';
/* language is remembered in 3 places so it follows you to every page: ?lang= in the URL, window.name (same tab) and localStorage */
try{lang=localStorage.getItem('lang')||''}catch(e){}
{const m=(window.name||'').match(/lang=(en|es)/);if(m)lang=m[1];
 const q=new URLSearchParams(location.search).get('lang');if(q==='en'||q==='es')lang=q}
if(lang!=='en'&&lang!=='es')lang='en';
function saveLang(){try{localStorage.setItem('lang',lang)}catch(e){}
 window.name=(window.name||'').replace(/lang=(en|es);?/,'')+'lang='+lang+';'}
saveLang();
function applyLang(){
 document.documentElement.lang=lang;
 document.querySelectorAll('[data-i18n]').forEach(el=>{
  const s=i18n[lang][el.dataset.i18n];
  if(s!==undefined)el.textContent=s.replace('{n}',el.dataset.n||'')});
 const b=document.getElementById('langBtn');
 if(b)b.textContent=lang==='en'?'🌐 ES':'🌐 EN';
 const t=document.getElementById('toTop');if(t)t.title=i18n[lang].top;
 renderMember()}
let lb=document.getElementById('langBtn');
if(!lb){const nv=document.querySelector('nav');if(nv){lb=document.createElement('button');lb.className='lang-btn';lb.id='langBtn';lb.type='button';nv.appendChild(lb)}}
if(lb)lb.addEventListener('click',()=>{lang=lang==='en'?'es':'en';saveLang();applyLang()});
applyLang();

/* ===== BACK TO TOP + HEADER ===== */
const tt=document.getElementById('toTop'),hd=document.querySelector('header');
function onScroll(){if(tt)tt.classList.toggle('show',scrollY>300);if(hd)hd.classList.toggle('scrolled',scrollY>40)}
window.addEventListener('scroll',onScroll,{passive:true});onScroll();
if(tt)tt.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}));

